package main

import (
	"os"

	"github.com/KogenAI/kogen-coordinator/project"
	"github.com/KogenAI/kogen-loop/sys"
	"github.com/KogenAI/kogen-verification/verify"
	"kogen/readiness"
)

// printReadiness does not change init's exit status.
func printReadiness(s *sys.Session, root, dir string) {
	home, _ := os.UserHomeDir()
	checks := readiness.Run(s, readiness.Input{Project: dir, Tools: verify.ToolsFromInstall(root), Version: versionLine(root), Home: home})
	s.Out(readiness.Text(checks))
	for _, check := range checks {
		if check.Status != "ok" {
			return
		}
	}
	cfg, err := project.LoadConfig(dir)
	if err != nil || cfg.Acceptance == nil || cfg.Acceptance.Run == "" || cfg.Acceptance.StepsDir == "" || len(cfg.Checks) == 0 {
		return
	}
	s.Puts("Next: kogen intent shape <slug> <request-file>")
}

